"""Summarize saved comparison runs; never calls a model or changes manuscript samples."""
import json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
full = root / 'runs/scene-vs-chapter-2026-10-16'
isolated = root / 'runs/scene-vs-chapter-isolated-2026-10-16'
first = json.loads((full / 'results.json').read_text())
second = json.loads((isolated / 'results.json').read_text())
rows = [('Сцены, весь план', first, 'scenes', full), ('Сцены, текущая карточка', second, 'scenes', isolated), ('Целая глава', first, 'chapter', full)]
lines = ['# Генерация по сценам или главами: сравнительный эксперимент', '',
'Предварительный вывод: этот прогон не подтвердил преимущество целой главы по литературному качеству. Сценовую генерацию пока следует сохранить как основной режим; главу целиком рассматривать как отдельный экспериментальный режим с проверкой объёма, времени повествования и исполнения событий.', '',
'## Метод', '',
f'Модель: `{first["model"]}`. Три независимых фиксированных контекста одной истории: непрерывное действие, диалог, переход между локациями. Русская проза, ограниченная точка зрения, прошедшее время. Для каждого текста цель 900 слов (800–1000); для сцен по 300 слов. Температура писателя 0.8, суммарный предел ответа 4800 токенов для каждого варианта главы. Тексты не редактировались и не сглаживались.', '',
'Первая серия: обоим вариантам доступен полный план главы. Вторая серия: сценовый писатель видит только текущую карточку, исходное состояние и весь уже написанный текст главы. Это контроль изоляции будущего, приближённый к рабочему принципу движка, но без полного производственного оркестратора, наблюдателя и ремонта. Три целые главы повторно использованы без регенерации. Итого девять уникальных текстов, а не двенадцать независимых образцов.', '',
'Одна выборка на сочетание главы и режима. У модели нет статистически значимого числа повторов; результаты относятся к этим коротким главам и одной модели. Системный запрос и точные промпты, ответы, время и счётчики токенов сохранены в JSON рядом с текстами. Оценщик — та же модель, два порядка A/B, температура 0.1. Корректность цитат проверяется программно, но литературная интерпретация остаётся модельным суждением.', '',
'## Фактический объём', '', '| Глава | Сцены с полным планом | Изолированные сцены | Целая глава |', '|---|---:|---:|---:|']
for index, case in enumerate(first['cases']):
    lines.append(f'| {case["plan"]["title"]} | {case["versions"]["scenes"]["metrics"]["words"]} | {second["cases"][index]["versions"]["scenes"]["metrics"]["words"]} | {case["versions"]["chapter"]["metrics"]["words"]} |')
lines += ['', 'Целевая длина была одинаковой, фактическая — разной. Это измеренный результат соблюдения задания и ограничение сравнения качества/скорости. Нельзя приписывать скорость короткой главы только способу генерации.', '',
'## Расход на генерацию трёх глав', '', '| Режим | Вызовы писателя | Всего слов | Входные токены | Выходные токены | Время вызовов, с |', '|---|---:|---:|---:|---:|---:|']
for title, run, mode, folder in rows:
    versions = [c['versions'][mode] for c in run['cases']]
    lines.append(f'| {title} | {9 if mode=="scenes" else 3} | {sum(v["metrics"]["words"] for v in versions)} | {sum(v["promptTokens"] for v in versions)} | {sum(v["outputTokens"] for v in versions)} | {sum(v["durationMs"] for v in versions)/1000:.1f} |')
lines += ['', 'Время и токены относятся к писателю, без оценщиков. Облачная задержка варьируется; это один прогон. Денежная стоимость не измерялась.', '',
'## Проверяемые наблюдения', '',
'1. В «Сухом следе» с полным планом второй сценовый вызов преждевременно написал эпизод архива. Третий повторил его: найдено 14 повторных предложений длиной от шести слов после нормализации. Это не 14 независимых сюжетных ошибок, а один большой повтор. При изоляции текущей карточки этот повтор в контрольном тексте отсутствует. Нельзя объяснять дефект только разбиением на сцены.',
'2. Целая диалоговая глава систематически нарушает требование прошедшего времени. Пример повествования: «Вера придвигает к себе акт, кладёт ладонь на верхний лист». Такая правка затрагивает повествование по всей главе, а не только стык эпизодов. Оценщик даже после добавления стилевого требования не дал устойчивого преимущества другой версии; автоматические баллы не заменяют чтение.',
'3. Три целые главы не попали в диапазон 800–1000 слов: две короче, одна длиннее. У сценового варианта тоже нет гарантии длины: в серии с изоляцией две главы короче диапазона.',
'4. В изолированном диалоге возникла отдельная ошибка с копией: героиня снимает «копирку», затем получает «зеркальный отпечаток её собственных букв» вместо нормально описанной копии подписанного акта. Локальная причинность и физические свойства предметов требуют проверки при обоих способах генерации.', '',
'## Устойчивость слепой оценки', '', '| Глава | Полный план: два предпочтения | Изоляция: два предпочтения |', '|---|---|---|']
for i, c in enumerate(first['cases']):
    def choices(case):
        return ', '.join(r['mapping'].get(r['review']['preferred'], 'tie') for r in case['reviews'])
    lines.append(f'| {c["plan"]["title"]} | {choices(c)} | {choices(second["cases"][i])} |')
lines += ['', 'В контрольной серии предпочтение меняется при перестановке текстов во всех трёх парах. Здесь нельзя объявлять победителя по голосам или усреднённым баллам. Повторная оценка тем же оценщиком не является независимым подтверждением.', '',
'## Объём исправлений', '',
'Ниже диапазон суммы repairWords по двум оценкам каждого текста. Это субъективная оценка затрагиваемых слов, не фактически выполненный ремонт и не измерение затрат. Она может пропускать ошибки (например, время повествования), поэтому не используется для выбора архитектуры.', '', '| Глава | Режим | Оценка затрагиваемых слов |', '|---|---|---:|']
for title, run, mode, folder in rows:
    for c in run['cases']:
        amounts=[]
        for r in c['reviews']:
            label=next(label for label,mapped in r['mapping'].items() if mapped==mode)
            amounts.append(sum(int(i.get('repairWords',0)) for i in r['review'][label]['issues']))
        lines.append(f'| {c["plan"]["title"]} | {title} | {min(amounts)}–{max(amounts)} |')
lines += ['', '## Решение для проекта', '',
'Не переключать основной движок на главы по результатам этого прогона. Сохранить сценовую причинную архитектуру и изоляцию будущего; целую главу исследовать отдельным режимом. До выбора нового значения по умолчанию нужны главы реальной рабочей длины, несколько повторов, независимая оценка без указания метода и измеренный ремонт до одинаковых критериев качества. В этом изменении производственный способ генерации не менялся.', '',
'## Тексты для чтения', '']
for i,c in enumerate(first['cases']):
    cid=c['plan']['id']
    lines += [f'### {c["plan"]["title"]}', '', f'- [Изолированные сцены]({isolated/cid}-scenes.md)', f'- [Целая глава]({full/cid}-chapter.md)', f'- [Сцены с полным планом]({full/cid}-scenes.md)', '']
lines += ['## Воспроизведение', '', 'Из корня проекта при работающем Vite на 127.0.0.1:3017:', '', '```sh', 'NOVEL_LIVE_COMPARISON=1 npm test -- tests/generationComparisonLive.test.ts', 'NOVEL_LIVE_COMPARISON=1 NOVEL_COMPARISON_ISOLATE=1 NOVEL_COMPARISON_DIR=runs/scene-vs-chapter-isolated-2026-10-16 npm test -- tests/generationComparisonLive.test.ts', 'python3 scripts/summarize-generation-comparison.py', '```', '', 'Совпадающие запросы переиспользуют сохранённые ответы. Для новых независимых образцов укажите другой NOVEL_COMPARISON_DIR. Обычный npm test не вызывает модель.']
output = full/'comparison.md'
output.write_text('\n'.join(lines))
print(output)
